<div class="admin-page-heading"><div><span class="admin-eyebrow">SERVICE CONTENT</span><p>Use clear, accurate service descriptions. Do not publish unconfirmed offerings.</p></div><a class="admin-text-link" href="<?= e(url('/admin/services')) ?>">← Back to services</a></div><section class="admin-panel form-panel"><form method="post" action="<?= e(url('/admin/services/save')) ?>" enctype="multipart/form-data" class="admin-form-grid"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($service['id']??'') ?>"><label>Service title *<input name="title" required value="<?= e($service['title']??'') ?>"></label><label>URL slug<input name="slug" value="<?= e($service['slug']??'') ?>"></label><label class="span-2">Short description<textarea name="short_description" rows="2" maxlength="300"><?= e($service['short_description']??'') ?></textarea></label><label class="span-2">Full description<textarea name="description" rows="6"><?= e($service['description']??'') ?></textarea></label><label>Icon name (optional)<input name="icon" value="<?= e($service['icon']??'paintbrush') ?>"></label><label>Service image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Display order<input type="number" name="sort_order" value="<?= e($service['sort_order']??0) ?>"></label><div class="form-checks"><label><input type="checkbox" name="is_published" value="1" <?= !isset($service['is_published'])||$service['is_published']?'checked':'' ?>> Publish on website</label></div><div class="span-2 admin-form-actions"><button class="admin-button" type="submit">Save Service <span>→</span></button><a class="admin-cancel" href="<?= e(url('/admin/services')) ?>">Cancel</a></div></form></section>
